R=[
("चीज़ी ब्रोकली स्पेगेटी स्क्वैश बेक",
"यह चीज़ी ब्रोकली स्पेगेटी स्क्वैश बेक पारंपरिक कैसरोल का आरामदायक, कम कार्बोहाइड्रेट वाला विकल्प है, जिसके हर निवाले में भरपूर फ़ाइबर और स्वाद है।",
"4","1/4 कैसरोल",
["1 मध्यम (लगभग 2-3 पाउंड) स्पेगेटी स्क्वैश","1 छोटा चम्मच ऑलिव ऑयल","1/4 छोटा चम्मच नमक","1/8 छोटा चम्मच काली मिर्च","2 कप ब्रोकली (फूल, कटे हुए)","2 कली लहसुन (बारीक कटी हुई)","1/2 कप कम सोडियम वाला सब्ज़ी का शोरबा","1/2 कप 1% दूध","1 छोटा चम्मच डिजॉन सरसों","1/2 छोटा चम्मच स्मोक्ड पेपरिका","1/4 कप चेडर चीज़ (कम वसा वाला, कद्दूकस किया हुआ)","1/4 कप सादा बिना वसा वाला ग्रीक योगर्ट","1/4 कप परमेसन चीज़ (कद्दूकस किया हुआ)"],
["ओवन को 400 डिग्री F पर पहले से गरम करें। स्क्वैश को लंबाई में आधा काटें और बीज निकाल दें। ऊपर से ऑलिव ऑयल, नमक और काली मिर्च छिड़कें। कटे हुए हिस्से को नीचे की ओर करके बेकिंग शीट पर रखें और काँटे से आसानी से धँसने तक, लगभग 35-40 मिनट भूनें। थोड़ा ठंडा होने दें, फिर काँटे से रेशों में अलग कर लें।","स्क्वैश भूनते समय, एक छोटे बर्तन में पानी उबालें। ब्रोकली डालें और बस नरम होने तक, लगभग 3 मिनट पकाएँ। पानी निथारें और एक तरफ़ रख दें।","एक बड़ी कड़ाही में मध्यम आँच पर थोड़ा-सा ऑलिव ऑयल डालें और लहसुन को खुशबू आने तक, लगभग 30 सेकंड पकाएँ। शोरबा, दूध, डिजॉन सरसों और पेपरिका मिलाएँ। 2-3 मिनट धीमी आँच पर पकाएँ।","आँच धीमी करें और चेडर चीज़ के पिघलकर चिकना होने तक चलाएँ।","फटने से बचाने के लिए, ग्रीक योगर्ट डालने से पहले सॉस को आँच से उतार लें। पहले 1-2 बड़े चम्मच गरम सॉस को योगर्ट में मिलाकर उसे संतुलित करें, फिर धीरे-धीरे कड़ाही में चलाकर मिलाएँ।","एक बड़े मिक्सिंग बाउल में स्पेगेटी स्क्वैश, ब्रोकली और चीज़ सॉस मिलाएँ। बेकिंग डिश में डालें और ऊपर से परमेसन चीज़ छिड़कें। 400°F पर 10 मिनट, या चीज़ के पिघलने और हल्का सुनहरा होने तक बेक करें।"],[]),
("ताज़ी रोज़मेरी के साथ बेक्ड कॉड फ़िले",
"घर पर वैलेंटाइन डे के रात के खाने के लिए इस हल्की लेकिन स्वादिष्ट रेसिपी को आज़माएँ। इसमें केवल 6 सामग्री लगती हैं और यह कुछ ही मिनटों में तैयार हो सकती है।",
"2","3 औंस मछली",
["4-6 टहनी ताज़ी रोज़मेरी","8 औंस कॉड फ़िले (लगभग 1/4 इंच मोटे, धोए और थपथपाकर सुखाए हुए)","1/2 छोटा चम्मच ऑलिव ऑयल","1 छोटा चम्मच ताज़ा नींबू का रस","1/8 छोटा चम्मच नमक","1/8 छोटा चम्मच काली मिर्च"],
["ओवन को 350 डिग्री F पर पहले से गरम करें। रोज़मेरी को एक छोटे बेकिंग पैन, जैसे 8 इंच के चौकोर पैन, में एक कतार में रखें। ऊपर कॉड फ़िले रखें। मछली पर तेल लगाएँ। नींबू का रस, नमक और काली मिर्च छिड़कें।","7 से 8 मिनट तक, या जब तक काँटे से जाँचने पर मछली आसानी से रेशे-रेशे न हो जाए, बेक करें।"],[]),
("मीठे प्याज़, सफ़ेद बीन्स और आर्टिचोक का डिप",
"यह डिप ज़्यादा कैलोरी और ज़्यादा वसा वाले पालक आर्टिचोक डिप का बढ़िया विकल्प है। इसे छुट्टियों के समारोहों में स्टार्टर के रूप में ले जाएँ या घर पर स्नैक के रूप में खाएँ।",
"20","लगभग 1 बड़ा चम्मच",
["2 बड़े चम्मच ऑलिव ऑयल","1 छोटा विडालिया या अन्य मीठा प्याज़ (कटा हुआ)","1 1/2 छोटे चम्मच चीनी","4 कली लहसुन (बारीक कटी हुई)","1 (15 औंस) कैन कैनेलिनी बीन्स (छानी और धोई हुई)","2 बड़े चम्मच नींबू का रस (ताज़ा)","1 छोटा चम्मच सूखा ओरेगानो","1 छोटा चम्मच सूखी तुलसी","1/8 छोटा चम्मच लाल मिर्च (कायेन पेपर)","1/8 छोटा चम्मच समुद्री नमक","1/8 छोटा चम्मच काली मिर्च (ताज़ी पिसी)","1 (14 औंस) कैन आर्टिचोक हार्ट्स (छाने हुए)","1/4 कप सूखे टमाटर (भिगोकर नरम किए हुए, बारीक कटे हुए)"],
["एक कड़ाही में मध्यम-तेज़ आँच पर तेल गरम करें। प्याज़, चीनी और लहसुन डालें और 5 मिनट भूनें।","इस मिश्रण को ब्लेंडर या फ़ूड प्रोसेसर में डालें। बाकी सामग्री डालें और चिकना, लेकिन गाढ़ा होने तक पीसें।"],[]),
("नींबू-खसखस ड्रेसिंग के साथ पालक और लाल प्याज़ का सलाद",
"हमारे पालक और लाल प्याज़ के सलाद के साथ ताज़गी की बौछार का आनंद लें, जिसमें तीखी नींबू-खसखस ड्रेसिंग है। मिलाने पर, यह सलाद आपको बनावट और स्वादों के सुखद मेल का आनंद लेने का न्योता देता है, और आपके भोजन में ताज़गी भरा इज़ाफ़ा करता है।",
"4","1 कप",
["8 कप बेबी पालक","1 छोटा लाल प्याज़ (पतला कटा हुआ)","1/2 कप चेरी टमाटर (आधे कटे हुए)","1/4 कप बादाम की कतरन (भुनी हुई)","1/4 कप सूखे क्रैनबेरी (बिना चीनी मिलाए)","2 बड़े चम्मच ऑलिव ऑयल","1 बड़ा चम्मच नींबू का रस (ताज़ा)","1/2 बड़ा चम्मच डिजॉन सरसों","1 छोटा चम्मच शहद","1/2 छोटा चम्मच खसखस","1/4 छोटा चम्मच नमक","1/2 छोटा चम्मच काली मिर्च"],
["एक बड़े सलाद बाउल में ताज़ा बेबी पालक, पतला कटा लाल प्याज़, आधे कटे चेरी टमाटर, भुनी हुई बादाम की कतरन और सूखे क्रैनबेरी मिलाएँ।","एक छोटे कटोरे में ऑलिव ऑयल, ताज़ा नींबू का रस, डिजॉन सरसों, शहद, खसखस, नमक और काली मिर्च को फेंटकर मिलाएँ।","ड्रेसिंग को सलाद के ऊपर डालें। बराबर परत चढ़ाने के लिए धीरे से मिलाएँ।","स्वाद मिलने के लिए सलाद को 10 मिनट रखा रहने दें।"],[]),
("केले और मक्के के साथ बादाम टैपिओका",
"यह बादाम दूध वाला टैपिओका एशिया के कई हिस्सों में परोसे जाने वाले पारंपरिक नारियल दूध वाले टैपिओका सूप पर आधारित है। बादाम दूध वाला यह रूप मूल से कहीं हल्का है, और उतना ही स्वादिष्ट भी। इसे दूसरे फलों, या यहाँ तक कि शकरकंद और अरबी के साथ भी आज़माएँ!",
"16","1/2 कप",
["8 कप बिना चीनी का बादाम दूध","1/3 कप टैपिओका मोती (साबूदाना)","3 बड़े चम्मच एगेव नेक्टर","1/2 छोटा चम्मच कोशर नमक","2 पके केले (छिले और कटे हुए)","1 कप ताज़े या जमे हुए मीठे पीले मक्के के दाने","1 छोटा चम्मच तिल (भुने हुए)"],
["एक बड़े बर्तन में बादाम दूध डालें और तेज़ आँच पर उबालें। आँच को मध्यम-धीमी करें और टैपिओका मोती डालें, उन्हें अलग रखने के लिए लगातार चलाते रहें। पाम शुगर और नमक डालें और मोतियों के पूरी तरह पारदर्शी होने तक, लगभग 30 मिनट पकाना जारी रखें।","आँच बंद करें और केले और मक्का मिलाएँ। भुने हुए तिल से सजाकर परोसें।"],[]),
("ताज़ी बेरीज़ के साथ चीनी रहित योगर्ट पारफ़ेट",
"यह चीनी रहित पारफ़ेट आपके दिन की शुरुआत का स्वादिष्ट और सेहतमंद तरीका है! मिठास के लिए स्टीविया, सादे ग्रीक योगर्ट, ताज़ी बेरीज़ और आपकी पसंद के कुरकुरे टॉपिंग से बना यह उन सबके लिए स्वादिष्ट विकल्प है जो अपनी चीनी की मात्रा कम करना चाहते हैं। आप इस पारफ़ेट के ऊपर चिया सीड्स, कद्दूकस किया नारियल या कटे हुए मेवे भी डालकर देख सकते हैं। रास्पबेरी या स्ट्रॉबेरी जैसी अपनी पसंदीदा बेरी बदलकर इसे और अपने अनुसार बनाएँ। इस सेहतमंद, आसान सुबह के भोजन या दिन के बीच के स्नैक का आनंद लें!",
"1","1 पारफ़ेट",
["1 कप सादा बिना वसा वाला ग्रीक योगर्ट","1/2 कप ताज़ी ब्लूबेरी","5 बूँद तरल स्टीविया मिठास","2 छोटे चम्मच बादाम की कतरन (वैकल्पिक)"],
["एक कटोरे में ग्रीक योगर्ट और SweetLeaf Sweet Drops Clear को चम्मच से तब तक मिलाएँ जब तक मिश्रण मलाईदार न हो जाए।","अपने पारफ़ेट के लिए एक लंबा गिलास या छोटा कटोरा लें और तली में योगर्ट की एक परत डालें। ऊपर तक पहुँचने तक योगर्ट की परतों के बीच बेरीज़ और मेवे (वैकल्पिक) डालें। आनंद लें!","सुझाव: तैयार पारफ़ेट फ्रिज में बढ़िया रखा रहता है, जिससे चलते-फिरते आसानी से भोजन की तैयारी हो जाती है!"],[]),
("संतरे की ड्रेसिंग के साथ गाजर सलाद",
"संतरे की ड्रेसिंग वाले इस गाजर सलाद के चमकीले और तीखे स्वादों का आनंद लें। ताज़ी जड़ी-बूटियों, मीठे संतरे और कुरकुरी गाजर का मेल इसे किसी भी भोजन में ताज़गी भरा और पौष्टिक इज़ाफ़ा बनाता है।",
"4","1 कप",
["4 कप गाजर (कद्दूकस की हुई)","1/4 कप ताज़ा हरा धनिया (कटा हुआ)","1/4 कप ताज़ा पुदीना (कटा हुआ)","1/4 कप लाल प्याज़ (कटा हुआ)","1/4 कप संतरे का रस","2 बड़े चम्मच ऑलिव ऑयल","1 बड़ा चम्मच शहद","1 छोटा चम्मच संतरे का छिलका (ज़ेस्ट)","1/4 छोटा चम्मच नमक","1/2 छोटा चम्मच काली मिर्च"],
["एक बड़े कटोरे में कद्दूकस की हुई गाजर, कटा हरा धनिया, कटा पुदीना और कटा लाल प्याज़ मिलाएँ।","एक छोटे कटोरे में संतरे का रस, ऑलिव ऑयल, शहद, संतरे का छिलका, नमक और काली मिर्च को फेंटकर मिलाएँ।","ड्रेसिंग को गाजर के मिश्रण पर डालें और मिलाने के लिए चलाएँ।"],[]),
("काली मिर्च और सौंफ़ के साथ साबुत गेहूँ के क्रैकर रिंग (टारालि इंटेग्राली कॉन पेपे ए फ़िनोक्यो)",
"इटली के दक्षिणी प्रांत लाज़ियो, मोलीज़े, पूलिया, बाज़िलिकाटा, कैम्पानिया, अब्रुज़ो और कैलाब्रिया सभी स्टार्टर के साथ टारालि—कुरकुरी, क्रैकर जैसी ब्रेड—परोसने की परंपरा साझा करते हैं। पुराने समय में, इन क्रैकर को सुखाना इन्हें सुरक्षित रखने का तरीका था। आज, ये स्वाद और परंपरा की बात हैं। कैलाब्रिया में, ये क्रैकर सेंट एंथनी के पर्व के लिए बनाए जाते हैं। इन क्रैकर के पारंपरिक आकारों में छल्ले, रस्सी, चोटी, छड़ियाँ और घोड़े की नाल शामिल हैं। सुंदर रिबन से बँधी पारदर्शी सेलोफ़ेन की थैलियों में लपेटे जाने पर, टारालि सुरुचिपूर्ण उपहार बनते हैं।",
"2","3 ब्रेड रिंग",
["2 1/2 छोटे चम्मच एक्टिव ड्राई यीस्ट","3/4 कप गुनगुना पानी (बाँटकर)","2 कप साबुत गेहूँ का आटा या ग्लूटेन-मुक्त बेकिंग मिक्स, साथ ही काम की सतह के लिए थोड़ा अतिरिक्त","1 बड़ा चम्मच काली मिर्च (ताज़ी पिसी)","2 छोटे चम्मच सौंफ़","1/4 छोटा चम्मच कुचली हुई लाल मिर्च के फ्लेक्स","1/2 छोटा चम्मच अपरिष्कृत समुद्री नमक","3 1/2 बड़े चम्मच एक्स्ट्रा वर्जिन ऑलिव ऑयल (बाँटकर)","1 बड़े अंडे की सफ़ेदी (हल्की फेंटी हुई)"],
["एक छोटे कटोरे में 1/4 कप गुनगुने पानी में यीस्ट घोलें।","आटा, काली मिर्च, सौंफ़, मिर्च के फ्लेक्स और नमक को एक बड़े कटोरे में रखें। यीस्ट का मिश्रण, अतिरिक्त 1/2 कप गुनगुना पानी और 3 बड़े चम्मच ऑलिव ऑयल डालें। अच्छी तरह मिलाकर आटा गूँध लें।","आटे को हल्का आटा छिड़की सतह पर निकालें। ज़ोर से गूँधें, ज़रूरत हो तो थोड़ा और आटा मिलाएँ, लगभग 8–10 मिनट तक, जब तक आटा चिकना और लचीला न हो जाए।","एक बड़े कटोरे में बचा हुआ 1/2 छोटा चम्मच ऑलिव ऑयल लगाएँ और आटे को उसके अंदर रखें। आटे को पलटकर तेल से लपेटें, और प्लास्टिक रैप और साफ़ रसोई के तौलिये से ढक दें। आकार में दोगुना होने तक, लगभग 1 1/2 घंटे फूलने दें।","ओवन को 375°F पर पहले से गरम करें।","आटे को कटोरे से निकालें और एक छोटा टुकड़ा तोड़ें। इसे लगभग पेंसिल जितनी मोटी 6 इंच की रस्सी की तरह बेलें, और गोल आकार दें। सिरों को कसकर दबाकर जोड़ें, और रिंग को बिना चिकनाई वाली बेकिंग शीट पर रखें। बाकी आटे के साथ यही दोहराएँ। रिंग्स को साफ़ रसोई के तौलिये से ढक दें और आकार में दोगुना होने तक, लगभग 1 घंटे फूलने दें।","रिंग्स के ऊपरी हिस्से पर अंडे की सफ़ेदी लगाएँ और हल्का सुनहरा होने तक, 15–20 मिनट बेक करें। निकालें, रैक पर ठंडा करें, और कसकर ढके डिब्बे में एक महीने तक रखें।"],[]),
("टैरागन-सरसों कॉड",
"नींबू वाला सरसों का सॉस इस भुनी हुई कॉड मछली में चमकदार स्वाद जोड़ता है। यह जल्दी पकती है, जिससे यह सप्ताह के किसी भी दिन का आसान, लेकिन शानदार भोजन बन जाती है। भुने हुए आलू और ब्रोकली के साथ परोसें।",
"4","4 औंस मछली",
["1 मध्यम नींबू (फाँकों में कटा हुआ)","1/4 छोटा चम्मच काली मिर्च","1/4 छोटा चम्मच नमक","1 पाउंड कॉड फ़िले (4 हिस्सों में कटे हुए)","1 कली लहसुन (बारीक कटी हुई)","1 बड़ा चम्मच नींबू का रस","1 बड़ा चम्मच पानी","1 1/2 बड़े चम्मच ऑलिव ऑयल (बाँटकर)","1/2 बड़ा चम्मच मक्खन (नरम किया हुआ)","1 बड़ा चम्मच ताज़ा टैरागन (बारीक कटा हुआ)","2 बड़े चम्मच दरदरी डिजॉन सरसों"],
["ओवन को 450°F पर पहले से गरम करें।","एक छोटे कटोरे में सरसों, टैरागन, मक्खन, 1 बड़ा चम्मच ऑलिव ऑयल, पानी, नींबू का रस और लहसुन मिलाएँ; एक तरफ़ रख दें।","कॉड पर नमक और काली मिर्च छिड़कें। एक उथली ओवन-सुरक्षित कड़ाही में मध्यम-तेज़ आँच पर बचा हुआ 1/2 बड़ा चम्मच ऑलिव ऑयल गरम करें। कॉड डालें और एक तरफ़ 4 मिनट सेकें। कॉड को पलटें और दूसरी तरफ़ 2 मिनट सेकें।","सरसों का सॉस कॉड पर डालें और कड़ाही को ओवन में रखें; 2 से 3 मिनट भूनें। कॉड को नींबू की फाँकों के साथ परोसें।"],[]),
("त्ज़त्ज़िकी और सब्ज़ियाँ",
"पारंपरिक भूमध्यसागरीय त्ज़त्ज़िकी सॉस कम कार्बोहाइड्रेट वाली बिना स्टार्च की सब्ज़ियों को डुबोने के लिए एकदम सही है। इसे सलाद, सैंडविच या रैप के ऊपर टॉपिंग के रूप में भी उपयोग किया जा सकता है।",
"16","2 बड़े चम्मच त्ज़त्ज़िकी + लगभग 1/3 कप सब्ज़ियाँ",
["2 कप सादा दही (बिना वसा वाला)","1/2 मध्यम खीरा (छिला, बीज निकाला हुआ और कटा हुआ)","2 कली लहसुन (बड़ी, बारीक कटी हुई)","1/2 छोटा चम्मच सूखा डिल (इसकी जगह 1 बड़ा चम्मच कटा ताज़ा डिल भी उपयोग कर सकते हैं)","1/4 छोटा चम्मच नमक","2 छोटे चम्मच नींबू का रस","1 छोटा चम्मच ऑलिव ऑयल","6 कप ताज़ी सब्ज़ियाँ (अलग-अलग किस्में चुनें: ताज़ी हरी बीन्स (हल्की भाप में पकी), हरी, लाल या पीली शिमला मिर्च, गाजर, अजवाइन के डंठल (सेलेरी), तोरी, पीली स्क्वैश, टमाटर, खीरा, मूली, ब्रोकली और फूलगोभी)"],
["परोसने से 12-24 घंटे पहले, एक छन्नी में पेपर कॉफ़ी फ़िल्टर या चीज़क्लॉथ बिछाएँ। इसे कटोरे के ऊपर रखें। दही को कॉफ़ी फ़िल्टर में चम्मच से डालें, ढक दें और 12-14 घंटे फ्रिज में रखें।","अब दही गाढ़ा हो जाएगा। नीचे जमा हुआ तरल फेंक दें या सूप या ब्रेड में उपयोग करें। दही को फ़िल्टर से निकालकर एक छोटे कटोरे में रखें।","दही में खीरा, लहसुन, डिल, नमक, नींबू का रस और ऑलिव ऑयल मिलाएँ। परोसने से पहले एक घंटा फ्रिज में रखें।","इसे अलग-अलग सब्ज़ियों के साथ परोसें, जैसे: ताज़ी हरी बीन्स (हल्की भाप में पकी), हरी, लाल या पीली शिमला मिर्च, गाजर, अजवाइन के डंठल (सेलेरी), तोरी, पीली स्क्वैश, टमाटर, खीरा, मूली, ब्रोकली और फूलगोभी।"],[]),
("भाप में पकी गाजर",
"भाप में पकी गाजर की पोषण संबंधी जानकारी",
"1","1/2 कप",
["1/2 कप गाजर"],
["गाजर को धोएँ और छील लें।","इन्हें स्लाइस, स्टिक्स या छोटे टुकड़ों में काटें ताकि ये बराबर पकें।","एक बर्तन में स्टीमर बास्केट रखें और लगभग एक इंच पानी डालें।","मध्यम आँच पर पानी उबालें।","गाजर को स्टीमर बास्केट में डालें और बर्तन को ढक्कन से ढक दें।","गाजर को लगभग 5–10 मिनट भाप में पकाएँ, या जब तक काँटा चुभोने पर वे नरम न हों।","आँच से उतारें और गरम परोसें।"],[]),
("मैक्सिकन-प्रेरित नाश्ते का बाउल",
"तीखा और हल्के मसालेदार स्वाद वाला यह मैक्सिकन-प्रेरित नाश्ते का बाउल स्वाद की कलियों के लिए आनंददायक है। ताज़ी सब्ज़ियों और फूलगोभी के चावल के साथ, यह अपने दिन की शुरुआत का कम कार्बोहाइड्रेट वाला तरीका है।",
"4","रेसिपी का 1/4 (लगभग 245 ग्राम)",
["2 बड़े चम्मच कैनोला ऑयल","1/2 कप पीला प्याज़ (बारीक कटा हुआ)","1 1/2 कप जमे हुए फूलगोभी के चावल (फूलगोभी के चावल)","1/2 कप शिमला मिर्च (बारीक कटी हुई)","2/3 कप काली बीन्स (छानी और धोई हुई)","1/2 छोटा चम्मच पिसा जीरा","1/2 छोटा चम्मच चिली पाउडर","1/2 छोटा चम्मच काली मिर्च","1/8 छोटा चम्मच कोशर नमक","4 बड़े अंडे","1/2 कप सालसा","1/2 कप ताज़ा हरा धनिया","1 साबुत नींबू (परोसने के लिए फाँकों में कटा हुआ)"],
["एक कड़ाही में मध्यम आँच पर तेल गरम करें।","कटा हुआ प्याज़ डालें और नरम होने तक पकाएँ।","फूलगोभी के चावल डालें और नरम होना शुरू होने तक 3–5 मिनट पकाएँ।","कड़ाही में कटी हुई शिमला मिर्च, काली बीन्स, पिसा जीरा और चिली पाउडर डालें। 3–5 मिनट और पकाएँ। मिश्रण में नमक और काली मिर्च डालें।","मिश्रण को कड़ाही के एक तरफ़ धकेलें और अंडों के लिए गड्ढे बनाएँ।","हर गड्ढे में एक अंडा तोड़ें और सफ़ेदी के जमने तक पकाएँ, जबकि जर्दी अभी भी बहती रहे। चाहें तो अंडों को बराबर पकाने के लिए कड़ाही को ढक दें।","जब अंडे आपकी पसंद के अनुसार पक जाएँ, तो कड़ाही को आँच से उतार लें।","अंडे, फूलगोभी के चावल और सब्ज़ियों के मिश्रण को चार कटोरों में बाँटें।","हर कटोरे के ऊपर सालसा और, यदि उपयोग कर रहे हैं तो, ताज़ा हरा धनिया डालें। बगल में नींबू की फाँकों के साथ परोसें।"],[]),
("गर्मियों के फलों की स्मूदी",
"गर्मियों के ताज़े फलों का लाभ उठाकर एक ताज़गी भरी स्मूदी बनाएँ! या, साल के किसी भी समय गर्मियों के स्वादों का आनंद लेने के लिए जमे हुए फलों का उपयोग करें।",
"4","1 कप",
["1 कप ताज़ी ब्लूबेरी","1 कप कटी हुई ताज़ी स्ट्रॉबेरी","2 आड़ू (छिले, बीज निकाले और कटे हुए)","6 औंस आड़ू फ़्लेवर वाला ग्रीक स्टाइल योगर्ट (बिना वसा वाला)","1 कप बादाम दूध (बिना चीनी का)","2 बड़े चम्मच पिसे अलसी के बीज","1/2 कप बर्फ़"],
["सभी सामग्री को ब्लेंडर में मिलाएँ और चिकना होने तक पीसें।"],[]),
("सरल गर्मियों का खीरा और टमाटर सलाद",
"इस सरल सलाद के धोखे में न आएँ – यह सरल ज़रूर है, लेकिन बेहद ताज़गी भरा और स्वादिष्ट भी है। यह गर्मियों के बारबेक्यू में एकदम सही साइड डिश बनता है!",
"4","1 कप",
["1 बड़ा खीरा (छिला हुआ और आधा कटा हुआ)","10 1/2 औंस चेरी टमाटर","1/4 कप लाल प्याज़ (बारीक कटा हुआ)","2 बड़े चम्मच रेड वाइन विनेगर","1/8 छोटा चम्मच काली मिर्च","1 बड़ा चम्मच ऑलिव ऑयल","1/8 छोटा चम्मच कोशर नमक"],
["खीरे के हर आधे हिस्से को फिर आधा काटें और बड़े टुकड़ों में काटें। चेरी टमाटर को आधा काट लें।","खीरे को चेरी टमाटर और कटे लाल प्याज़ के साथ एक सलाद बाउल में रखें।","एक छोटे कटोरे में रेड वाइन विनेगर, काली मिर्च, ऑलिव ऑयल और नमक को फेंटें। ड्रेसिंग को सलाद के ऊपर डालें और परोसें।"],[]),
("भूमध्यसागरीय मसूर का सूप",
"मसूर फ़ाइबर से भरपूर, कार्बोहाइड्रेट का बहुत सेहतमंद स्रोत है। अगर आप इस सूप का कुछ हिस्सा किसी और दिन के लिए बचाना चाहते हैं, तो यह अच्छी तरह जम जाता है।",
"8","लगभग 1 कप",
["2 छोटे चम्मच कैनोला ऑयल","1 मध्यम प्याज़ (बारीक कटा हुआ)","2 कली लहसुन (बारीक कटी हुई)","6 औंस इटैलियन टर्की सॉसेज (आवरण से मांस निकालकर, कटा हुआ)","32 औंस कम सोडियम वाला चिकन शोरबा (कम सोडियम वाला, वसा रहित)","1 कैन डिब्बाबंद कटे हुए टमाटर (14 औंस, कटे हुए)","3 कप पानी","1 कप सूखी मसूर","1/2 छोटा चम्मच काली मिर्च","1/4 छोटा चम्मच सूखा ओरेगानो","1 तेज पत्ता"],
["एक बड़े सूप के बर्तन में मध्यम-तेज़ आँच पर तेल गरम करें। प्याज़ डालें और 3 मिनट, या पारदर्शी होने तक भूनें। लहसुन डालें और 30 सेकंड भूनें।","टर्की इटैलियन सॉसेज डालें और भूरा होने तक लगभग 8 मिनट पकाएँ। बाकी सामग्री डालें।","सूप को उबालें; आँच कम करें और 15 मिनट धीमी आँच पर पकाएँ।"],[]),
]
